parameters.jsCode:
// Sanitize the agent output so Telegram never rejects it for bad formatting entities.
const raw = $json.output != null ? String($json.output) : '';
let text = raw
  .replace(/```[a-zA-Z]*\n?/g, '') // opening code fences
  .replace(/```/g, '')             // closing code fences
  .replace(/[*_`~]/g, '')          // markdown emphasis / code chars
  .replace(/[<>]/g, '');           // angle brackets (HTML entities)
text = text.trim();
if (!text) {
  text = 'Maaf kijiye, main abhi jawab nahi de paya. Dobara koshish karein.';
}
return [{ json: { output: text } }];
